import { HttpClient } from '@angular/common/http';
import { computed, inject, Injectable, signal } from '@angular/core';
import { decodeTerms, isRecord, type Country, type Terms } from '@quote/contract';
import type { Subscription } from 'rxjs';
import { PlanState } from './plan-state';
import { QuoteState } from './quote-state';

type Outcome = 'approved' | 'rejected';
type Phase = 'idle' | 'loading' | 'ready' | 'unavailable' | 'checking' | 'processing';

type Consent = {
  terms: Terms;
  quote: string;
};

function receiptKey(country: Country) {
  return `quote-receipt-v1:${country}`;
}

function restoreReceipt(country: Country): string | null {
  try {
    const text = sessionStorage.getItem(receiptKey(country));
    if (!text || text.length > 256) return null;
    const input: unknown = JSON.parse(text);
    if (!isRecord(input) || input['version'] !== 1 || input['country'] !== country) return null;
    const number = input['number'];
    return typeof number === 'string' && /^DEMO-[A-F0-9]{24}$/.test(number) ? number : null;
  } catch {
